using AcxiomCRM.Backend.Data; using AcxiomCRM.Backend.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Backend.Controllers;
[ApiController,Route("api"),Authorize]
public class DashboardController(CrmDbContext db):ControllerBase
{
 [HttpGet("dashboard")] public async Task<IActionResult> Dashboard(){var customers=db.Customers.AsQueryable();var leads=db.Leads.AsQueryable();var opps=db.Opportunities.AsQueryable();var followups=db.FollowUps.AsQueryable();if(User.IsInRole("Sales Executive")){customers=customers.Where(x=>x.CreatedBy==User.Identity!.Name);leads=leads.Where(x=>x.Assigned==User.Identity!.Name);opps=opps.Where(x=>x.Assigned==User.Identity!.Name);followups=followups.Where(x=>x.Assigned==User.Identity!.Name);}var allOpps=await opps.ToListAsync();return Ok(new{totalCustomers=await customers.CountAsync(),totalLeads=await leads.CountAsync(),openLeads=await leads.CountAsync(x=>x.Status!="Lost"&&x.Status!="Converted"),totalOpportunities=allOpps.Count,openOpportunities=allOpps.Count(x=>x.Status=="Open"),wonOpportunities=allOpps.Count(x=>x.Status=="Won"),lostOpportunities=allOpps.Count(x=>x.Status=="Lost"),pipelineValue=allOpps.Where(x=>x.Status=="Open").Sum(x=>x.Amount),weightedPipelineValue=allOpps.Where(x=>x.Status=="Open").Sum(x=>x.WeightedValue),pendingFollowUps=await followups.CountAsync(x=>x.Status=="Planned"),leadStatuses=await leads.GroupBy(x=>x.Status).Select(g=>new{status=g.Key,count=g.Count()}).ToListAsync(),opportunityStages=allOpps.GroupBy(x=>x.Stage).Select(g=>new{stage=g.Key,count=g.Count(),amount=g.Sum(x=>x.Amount)}).ToList()});}
 [Authorize(Roles="Admin,Manager"),HttpGet("reports/pipeline")] public async Task<IActionResult> Pipeline(){var rows=await db.Opportunities.GroupBy(x=>new{x.Stage,x.Assigned}).Select(g=>new{g.Key.Stage,g.Key.Assigned,count=g.Count(),amount=g.Sum(x=>x.Amount),weightedAmount=g.Sum(x=>x.WeightedValue)}).ToListAsync();return Ok(rows);}
 [Authorize(Roles="Admin"),HttpGet("audit")] public async Task<IActionResult> Audit([FromQuery]string? entity){var q=db.AuditLogs.AsQueryable();if(!string.IsNullOrWhiteSpace(entity))q=q.Where(x=>x.Entity==entity);return Ok(await q.OrderByDescending(x=>x.Date).Take(500).ToListAsync());}
 [Authorize(Roles="Admin"),HttpGet("users")] public async Task<IActionResult> Users([FromServices]Microsoft.AspNetCore.Identity.UserManager<ApplicationUser> manager){var result=new List<object>();foreach(var u in await manager.Users.ToListAsync())result.Add(new{id=u.Id,name=u.FullName,email=u.Email,active=u.IsActive,roles=await manager.GetRolesAsync(u)});return Ok(result);}
}
